```systemverilog
module hough #(
    parameter int NT = 16,
    parameter int NR = 96,
    parameter int ROFF = 48
) (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        pt_valid,
    input  logic [7:0]  pt_x,
    input  logic [7:0]  pt_y,
    output logic        busy,
    input  logic        clear,
    input  logic [3:0]  rd_theta,
    input  logic [6:0]  rd_rho,
    output logic [15:0] rd_cnt
);

    (* ram_style = "block" *) logic [10:0] mem [0:1535];

    logic        clear_active;
    logic [10:0] clear_index;
    logic [3:0]  direction;

    logic [4:0] x_hold, y_hold;
    logic [3:0] launch_dir;
    logic        start_point, launch;

    logic signed [5:0]  x_r, y_r;
    logic signed [8:0]  cos_r, sin_r;
    logic signed [14:0] mx_m, my_m;
    logic signed [14:0] px_p, py_p;
    logic signed [15:0] sum_s;

    logic [3:0] d1, d2, d3, d4;
    logic v1, v2, v3, v4, v5;

    logic signed [16:0] rounded_sum;
    logic signed [10:0] rho_calc, bin_calc;
    logic [10:0] projection_addr, addr_stage, addr_hold;
    logic [10:0] mem_q;
    logic        wr_pending;

    logic [10:0] read_addr;
    logic [10:0] sat_inc;

    function automatic logic signed [8:0] cos_coeff(input logic [3:0] idx);
        case (idx)
            4'd0:  cos_coeff =  9'sd128;
            4'd1:  cos_coeff =  9'sd126;
            4'd2:  cos_coeff =  9'sd118;
            4'd3:  cos_coeff =  9'sd106;
            4'd4:  cos_coeff =   9'sd91;
            4'd5:  cos_coeff =   9'sd71;
            4'd6:  cos_coeff =   9'sd49;
            4'd7:  cos_coeff =   9'sd25;
            4'd8:  cos_coeff =    9'sd0;
            4'd9:  cos_coeff =  -9'sd25;
            4'd10: cos_coeff =  -9'sd49;
            4'd11: cos_coeff =  -9'sd71;
            4'd12: cos_coeff =  -9'sd91;
            4'd13: cos_coeff = -9'sd106;
            4'd14: cos_coeff = -9'sd118;
            default: cos_coeff = -9'sd126;
        endcase
    endfunction

    function automatic logic signed [8:0] sin_coeff(input logic [3:0] idx);
        case (idx)
            4'd0:  sin_coeff =    9'sd0;
            4'd1:  sin_coeff =   9'sd25;
            4'd2:  sin_coeff =   9'sd49;
            4'd3:  sin_coeff =   9'sd71;
            4'd4:  sin_coeff =   9'sd91;
            4'd5:  sin_coeff =  9'sd106;
            4'd6:  sin_coeff =  9'sd118;
            4'd7:  sin_coeff =  9'sd126;
            4'd8:  sin_coeff =  9'sd128;
            4'd9:  sin_coeff =  9'sd126;
            4'd10: sin_coeff =  9'sd118;
            4'd11: sin_coeff =  9'sd106;
            4'd12: sin_coeff =   9'sd91;
            4'd13: sin_coeff =   9'sd71;
            sin_coeff = sin_coeff;
            4'd14: sin_coeff =   9'sd49;
            default: sin_coeff =   9'sd25;
        endcase
    endfunction

    always_comb begin
        start_point = !busy && !clear_active && !clear && pt_valid;
        launch = start_point ||
                 (wr_pending && busy && !clear_active && (direction != 4'd15));

        if (start_point)
            launch_dir = 4'd0;
        else
            launch_dir = direction + 4'd1;

        rounded_sum = $signed({sum_s[15], sum_s}) + 17'sd64;
        rho_calc = rounded_sum >>> 7;
        bin_calc = rho_calc + 11'sd48;
        projection_addr =
            ({7'd0, d4} * 11'd96) + bin_calc[10:0];

        read_addr = (rd_theta * 11'd96) + {4'd0, rd_rho};

        if (mem_q == 11'h7ff)
            sat_inc = 11'h7ff;
        else
            sat_inc = mem_q + 11'd1;
    end

    // DSP pipeline: operand registers, multiply registers, and product registers.
    // These registers intentionally have no reset.
    always_ff @(posedge clk) begin
        if (launch) begin
            if (start_point) begin
                x_r   <= $signed({1'b0, pt_x[4:0]});
                y_r   <= $signed({1'b0, pt_y[4:0]});
            end else begin
                x_r   <= $signed({1'b0, x_hold});
                y_r   <= $signed({1'b0, y_hold});
            end
            cos_r <= cos_coeff(launch_dir);
            sin_r <= sin_coeff(launch_dir);
            d1    <= launch_dir;
        end else begin
            x_r   <= '0;
            y_r   <= '0;
            cos_r <= '0;
            sin_r <= '0;
            d1    <= '0;
        end

        mx_m <= x_r * cos_r;
        my_m <= y_r * sin_r;
        px_p <= mx_m;
        py_p <= my_m;
        sum_s <= $signed(px_p) + $signed(py_p);

        d2 <= d1;
        d3 <= d2;
        d4 <= d3;

        if (v4)
            addr_stage <= projection_addr;

        if (v5)
            addr_hold <= addr_stage;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            v1         <= 1'b0;
            v2         <= 1'b0;
            v3         <= 1'b0;
            v4         <= 1'b0;
            v5         <= 1'b0;
            wr_pending <= 1'b0;
        end else begin
            v1         <= launch;
            v2         <= v1;
            v3         <= v2;
            v4         <= v3;
            v5         <= v4;
            wr_pending <= v5;
        end
    end

    // Control and clear sequencing.
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy         <= 1'b0;
            clear_active <= 1'b0;
            clear_index  <= '0;
            direction    <= '0;
        end else if (clear_active) begin
            if (clear_index == 11'd1535) begin
                clear_active <= 1'b0;
                busy         <= 1'b0;
            end else begin
                clear_index <= clear_index + 11'd1;
            end
        end else if (!busy) begin
            if (clear) begin
                clear_active <= 1'b1;
                clear_index  <= '0;
                busy         <= 1'b1;
            end else if (pt_valid) begin
                busy      <= 1'b1;
                direction <= 4'd0;
                x_hold    <= pt_x[4:0];
                y_hold    <= pt_y[4:0];
            end
        end else if (wr_pending) begin
            if (direction == 4'd15)
                busy <= 1'b0;
            else
                direction <= direction + 4'd1;
        end
    end

    // Single-port synchronous accumulator memory.
    always_ff @(posedge clk) begin
        if (clear_active) begin
            mem[clear_index] <= 11'd0;
        end else if (wr_pending) begin
            mem[addr_hold] <= sat_inc;
        end else if (v5) begin
            mem_q <= mem[addr_stage];
        end else if (!busy && !clear_active && !start_point && !clear) begin
            if (rd_rho < 7'd96)
                mem_q <= mem[read_addr];
            else
                mem_q <= 11'd0;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            rd_cnt <= 16'd0;
        else if (!busy && !clear_active)
            rd_cnt <= {5'd0, mem_q};
    end

endmodule
```
NOTE: Six pipeline stages from point launch to synchronous BRAM read; each point takes about 96 clocks to update all 16 bins, and CLEAR takes 1536 clocks. Expected resources: two DSP48E1s and one BRAM36-equivalent, plus control and carry-chain logic.

